// ProductList.tsx
// Generated by CodeCreator
import { useState, useCallback } from 'react';
import type { GridSortModel } from '@mui/x-data-grid';
import { type GridColDef, GridActionsCellItem } from '@mui/x-data-grid';
import { Box, Alert, Button, Dialog, DialogTitle, DialogContent } from '@mui/material';
import { Visibility as ViewIcon } from '@mui/icons-material';
import { ContentCopy as ContentCopyIcon } from '@mui/icons-material';
import { OpenInNew as OpenInNewIcon } from '@mui/icons-material';
import { Edit as EditIcon } from '@mui/icons-material';
import { Delete as DeleteIcon } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { useProducts, useUpdateProduct, useDeleteProduct } from '../hooks/useProduct';
import AppDataGrid from '../components/shared/AppDataGrid';
import ConfirmDialog from '../components/shared/ConfirmDialog';
import { useEnumValues } from '../hooks/useEnumValues';
import { useNotification } from '../contexts/NotificationContext';
import { PermissionGate } from '../contexts/AuthContext';
import ProductForm from './ProductForm';
import type { UpdateProductRequest } from '../types/Product';
import FilterBuilder from '../components/shared/FilterBuilder';
import FilterListIcon from '@mui/icons-material/FilterList';
import he from '../i18n/he';
import { Collapse } from '@mui/material';

export default function ProductList() {
  const [paginationModel, setPaginationModel] = useState({ page: 0, pageSize: 25 });
  const [search, setSearch] = useState('');
  const [sortModel, setSortModel] = useState<GridSortModel>([]);
  const [showFilters, setShowFilters] = useState(false);
  const [activeFilters, setActiveFilters] = useState<Record<string, unknown>>({});
  const sortField = sortModel[0]?.field ?? '';
  const sortDir = sortModel[0]?.sort ?? 'asc';
  const handleSortModelChange = useCallback((model: GridSortModel) => {
    setSortModel(model);
    setPaginationModel((prev) => ({ ...prev, page: 0 }));
  }, []);
  const { data, isLoading, isError, error } = useProducts(paginationModel.page, paginationModel.pageSize, search, sortField, sortDir);
  const deleteMutation = useDeleteProduct();
  const [deleteId, setDeleteId] = useState<number | null>(null);
  const [selectedIds, setSelectedIds] = useState<(string | number)[]>([]);
  const [bulkDeleteConfirm, setBulkDeleteConfirm] = useState(false);
  const navigate = useNavigate();
  const { showSuccess } = useNotification();
  const updateMutation = useUpdateProduct();
  const [quickCreateOpen, setQuickCreateOpen] = useState(false);
  const enmCategoryOptions = useEnumValues('Category');

  const columns: GridColDef[] = [
    { field: 'id', headerName: 'ID', width: 80, type: 'number' },
    { field: 'productCode', headerName: 'Product Code', flex: 1, minWidth: 150 },
    { field: 'productName', headerName: 'Product Name', flex: 1, minWidth: 150 },
    {
      field: 'enmCategory',
      headerName: 'Category',
      width: 150,
      valueFormatter: (value) => {
        const opt = enmCategoryOptions.find((o) => o.value === value);
        return opt ? opt.label : String(value ?? '');
      },
    },
    { field: 'unitOfMeasure', headerName: 'Unit Of Measure', flex: 1, minWidth: 150 },
    { field: 'notes', headerName: 'Notes', flex: 1, minWidth: 150 },
    { field: 'isActive', headerName: 'Is Active', width: 100, type: 'boolean' },
    { field: 'currentStock', headerName: 'Current Stock', width: 120 },
    { field: 'baseCost', headerName: 'Base Cost', width: 130 },
    {
      field: 'actions',
      type: 'actions',
      headerName: 'Actions',
      width: 140,
      getActions: (params) => [
        <GridActionsCellItem
          key="view"
          icon={<ViewIcon />}
          label="View"
          onClick={() => navigate(`/products/${params.id}`)}
        />,
        <GridActionsCellItem
          key="edit"
          icon={<EditIcon />}
          label="Edit"
          onClick={() => navigate(`/products/${params.id}/edit`)}
        />,
        <GridActionsCellItem
          key="delete"
          icon={<DeleteIcon />}
          label="Delete"
          onClick={() => setDeleteId(params.id as number)}
        />,
      ],
    },
  ];

  if (isError) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error" sx={{ mb: 2 }}>
          Failed to load products: {(error as Error)?.message || 'Unknown error'}
        </Alert>
      </Box>
    );
  }

  const filterFields = [
    { field: 'productCode', label: 'Product Code', type: 'string' as const },
    { field: 'productName', label: 'Product Name', type: 'string' as const },
    { field: 'enmCategory', label: 'Category', type: 'string' as const },
    { field: 'unitOfMeasure', label: 'Unit Of Measure', type: 'string' as const },
    { field: 'notes', label: 'Notes', type: 'string' as const },
    { field: 'isActive', label: 'Is Active', type: 'boolean' as const },
    { field: 'currentStock', label: 'Current Stock', type: 'number' as const },
    { field: 'baseCost', label: 'Base Cost', type: 'number' as const },
  ];

  return (
    <Box sx={{ p: 3 }}>
      <Box display="flex" justifyContent="flex-end" mb={1}>
        <Button size="small" startIcon={<FilterListIcon />} onClick={() => setShowFilters((p) => !p)} color={Object.keys(activeFilters).length > 0 ? 'primary' : 'inherit'}>
          {showFilters ? he.actions.hideFilters : `${he.actions.filter}${Object.keys(activeFilters).length > 0 ? ` (${Object.keys(activeFilters).length})` : ''}`}
        </Button>
      </Box>
      <Collapse in={showFilters}>
        <FilterBuilder fields={filterFields} onApply={(f) => { setActiveFilters(f as Record<string, unknown>); setPaginationModel((p) => ({ ...p, page: 0 })); }} onClear={() => setActiveFilters({})} />
      </Collapse>
      <AppDataGrid
        entityName="product"
        title="Product List"
        rows={data?.items || []}
        columns={columns}
        loading={isLoading}
        getRowId={(row) => (row as any).id as string | number}
        rowCount={data?.total || 0}
        paginationModel={paginationModel}
        onPaginationModelChange={setPaginationModel}
        serverSearch={search}
        onServerSearchChange={setSearch}
        sortModel={sortModel}
        onSortModelChange={handleSortModelChange}
        onRowClick={(id) => navigate(`/products/${id}`)}
        checkboxSelection
        onSelectionChange={(ids) => setSelectedIds(ids)}
        onContextMenuActions={(id, row) => [
          { label: he.actions.view, icon: <OpenInNewIcon fontSize="small" />, onClick: () => navigate(`/products/${id}`) },
          { label: he.actions.copyId, icon: <ContentCopyIcon fontSize="small" />, onClick: () => { navigator.clipboard.writeText(String(id)); showSuccess(he.messages.idCopied); } },
          { label: he.actions.copyRow, icon: <ContentCopyIcon fontSize="small" />, onClick: () => { navigator.clipboard.writeText(JSON.stringify(row, null, 2)); showSuccess(he.messages.rowCopied); } },
          { label: he.actions.duplicate, icon: <ContentCopyIcon fontSize="small" />, onClick: () => navigate(`/products/new?cloneFrom=${id}`), divider: true },
          { label: he.actions.edit, icon: <EditIcon fontSize="small" />, onClick: () => navigate(`/products/${id}/edit`) },
          { label: he.actions.delete, icon: <DeleteIcon fontSize="small" />, onClick: () => setDeleteId(id as number), divider: true },
        ]}
        onCreateNew={() => navigate('/products/new')}
        editable
        processRowUpdate={async (newRow, oldRow) => { await updateMutation.mutateAsync({ id: (newRow as any).id as number, data: newRow as unknown as UpdateProductRequest }); return newRow; }}
        onBulkEdit={async (ids, field, value) => {
          await Promise.all(ids.map((id) => updateMutation.mutateAsync({ id: id as number, data: { [field]: value } as unknown as UpdateProductRequest })));
        }}
        bulkEditableFields={[
          { field: 'productCode', label: 'Product Code', type: 'string' },
          { field: 'productName', label: 'Product Name', type: 'string' },
          { field: 'enmCategory', label: 'Category', type: 'select' },
          { field: 'unitOfMeasure', label: 'Unit Of Measure', type: 'string' },
          { field: 'notes', label: 'Notes', type: 'string' },
          { field: 'baseCost', label: 'Base Cost', type: 'number' },
        ]}
        headerActions={
          <>
            <PermissionGate entity="product" action="delete">
              {selectedIds.length > 0 && (
                <Button variant="outlined" color="error" onClick={() => setBulkDeleteConfirm(true)}>
                  {he.actions.bulkDelete} ({selectedIds.length})
                </Button>
              )}
            </PermissionGate>
            <PermissionGate entity="product" action="write">
              <Button variant="contained" onClick={() => navigate('/products/new')}>
                {he.actions.create}
              </Button>
              <Button variant="outlined" onClick={() => setQuickCreateOpen(true)}>
                {he.actions.quickCreate}
              </Button>
            </PermissionGate>
          </>
        }
      />
      <Dialog open={quickCreateOpen} onClose={() => setQuickCreateOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Quick Create Product</DialogTitle>
        <DialogContent>
          <ProductForm embedded onSuccess={() => setQuickCreateOpen(false)} />
        </DialogContent>
      </Dialog>
      <ConfirmDialog
        open={deleteId !== null}
        title="Delete Product"
        message="Are you sure you want to delete this product? This action cannot be undone."
        confirmDisabled={deleteMutation.isPending}
        onConfirm={() => {
          if (deleteId !== null) {
            deleteMutation.mutate(deleteId);
          }
          setDeleteId(null);
        }}
        onCancel={() => setDeleteId(null)}
      />
      <ConfirmDialog
        open={bulkDeleteConfirm}
        title="Delete Multiple Products"
        message={`Are you sure you want to delete ${selectedIds.length} product(s)? This action cannot be undone.`}
        severity="error"
        onConfirm={async () => {
          try {
            await Promise.all(selectedIds.map((id) => deleteMutation.mutateAsync(id as number)));
          } catch { /* individual errors handled by mutation onError */ }
          setSelectedIds([]);
          setBulkDeleteConfirm(false);
        }}
        onCancel={() => setBulkDeleteConfirm(false)}
      />
    </Box>
  );
}

